"""Process helpers — kill trees for Demucs / long-running children."""

from __future__ import annotations

import logging
import os
import signal
import subprocess
from typing import Any

_log = logging.getLogger("transub_engine.proc_util")


def kill_process_tree(proc: Any, *, reason: str = "") -> None:
    """Best-effort kill of a Popen process and its children."""
    if proc is None:
        return
    try:
        if proc.poll() is not None:
            return
    except Exception:
        return

    pid = getattr(proc, "pid", None)
    if not pid:
        try:
            proc.kill()
        except Exception:
            pass
        return

    _log.info("kill_process_tree pid=%s reason=%s", pid, reason or "-")
    if os.name == "nt":
        try:
            subprocess.run(
                ["taskkill", "/PID", str(pid), "/T", "/F"],
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                check=False,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                timeout=15,
            )
        except Exception as err:
            _log.warning("taskkill failed for %s: %s", pid, err)
            try:
                proc.kill()
            except Exception:
                pass
        return

    try:
        os.killpg(os.getpgid(pid), signal.SIGTERM)
    except Exception:
        try:
            proc.terminate()
        except Exception:
            pass
    try:
        proc.wait(timeout=3)
    except Exception:
        try:
            os.killpg(os.getpgid(pid), signal.SIGKILL)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass
